import litellm
import logging
import importlib.util
import sys
import os
import concurrent.futures
import json
from typing import Optional, List, Dict, Any
from .config import AgentConfig, ModelType
from .skills_runtime import SkillRuntime, build_tool_messages

# Optional: Disable extreme litellm verbosity for normal usage
litellm.suppress_debug_info = True

# Custom JSON formatting or extra logic can be added here
logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)

class Agent:
    def __init__(self, config: AgentConfig):
        self.config = config
        self.name = config.name
        self.model = config.model
        self.model_type = config.model_type
        self.system_prompt = config.system_prompt
        self.expertise = config.expertise
        self._skill_runtime = SkillRuntime(config)
        self._last_skill_events: List[Dict[str, Any]] = []

    def _execute_custom_function(self, messages: List[Dict[str, str]]) -> str:
        """Dynamically loads and invokes a custom python function for inference."""
        file_path = self.config.custom_function_path
        func_name = self.config.custom_function_name

        if not file_path or not func_name:
            return "[Error: Custom function path or name not provided]"

        if not os.path.isfile(file_path):
            return f"[Error: File not found: {file_path}]"

        try:
            # Dynamically import the module from the path
            spec = importlib.util.spec_from_file_location("custom_model_module", file_path)
            module = importlib.util.module_from_spec(spec)
            sys.modules["custom_model_module"] = module
            spec.loader.exec_module(module)

            # Get the function
            inference_func = getattr(module, func_name)

            # We enforce standard (messages: List[Dict]) -> str signature for custom functions
            with concurrent.futures.ThreadPoolExecutor(max_workers=1) as executor:
                future = executor.submit(inference_func, messages)
                try:
                    response = future.result(timeout=self.config.timeout)
                    return str(response).strip()
                except concurrent.futures.TimeoutError:
                    return f"[Timeout Error: The custom function '{func_name}' took too long to respond ({self.config.timeout}s)]"

        except AttributeError:
             return f"[Error: Function '{func_name}' not found in {file_path}]"
        except Exception as e:
            logger.error(f"Error executing custom function '{func_name}' in {file_path}: {e}")
            return f"[Error: Custom function failed. Details: {str(e)}]"

    def consume_last_skill_events(self) -> List[Dict[str, Any]]:
        """Return and clear structured skill events for the last generation call."""
        events = list(self._last_skill_events)
        self._last_skill_events = []
        return events

    def generate_response_with_events(
        self, context_messages: List[Dict[str, str]], override_params: Optional[Dict[str, Any]] = None
    ) -> Dict[str, Any]:
        """
        Generate a response and structured skill execution events.
        """
        params = override_params or {}
        self._last_skill_events = []

        # Build the system message for this agent
        full_system_prompt = self.config.system_prompt
        if self.config.custom_instructions:
            full_system_prompt += f"\n\nADDITIONAL INSTRUCTIONS FOR THIS SESSION:\n{self.config.custom_instructions}"
        if self._skill_runtime.has_skills:
            skill_instructions = self._skill_runtime.get_combined_instructions()
            if skill_instructions:
                full_system_prompt += (
                    "\n\nAVAILABLE TOOLS:\n"
                    "You may call tools when needed and then summarize outputs clearly for the user.\n\n"
                    f"{skill_instructions}"
                )

        messages = [{"role": "system", "content": full_system_prompt}]
        messages.extend(context_messages)

        if self.model_type == ModelType.CUSTOM_FUNCTION:
            content = self._execute_custom_function(messages)
            return {"content": content, "skill_events": []}

        try:
            # LiteLLM handling
            litellm_params = {
                "model": self.model,
                "messages": messages,
                "temperature": self.config.temperature
            }
            if self.config.max_tokens:
                litellm_params["max_tokens"] = self.config.max_tokens

            litellm_params["timeout"] = self.config.timeout
            litellm_params.update(params)
            tools = self._skill_runtime.get_tools()
            if self._skill_runtime.has_skills and self._skill_runtime.load_error:
                return {"content": f"[Error: {self._skill_runtime.load_error}]", "skill_events": []}
            if tools:
                litellm_params["tools"] = tools
                litellm_params["tool_choice"] = "auto"

            response = litellm.completion(**litellm_params)
            first_message = response.choices[0].message
            tool_calls = list(getattr(first_message, "tool_calls", []) or [])

            if tools and tool_calls:
                if len(tool_calls) > self.config.max_skill_calls_per_turn:
                    return {
                        "content": (
                            "[Error: Model requested too many tool calls in one turn "
                            f"({len(tool_calls)} > {self.config.max_skill_calls_per_turn})]"
                        ),
                        "skill_events": [],
                    }

                tool_call_payload: List[Dict[str, Any]] = []
                tool_results: List[Dict[str, Any]] = []
                skill_events: List[Dict[str, Any]] = []
                for tc in tool_calls:
                    func = getattr(tc, "function", None)
                    tool_name = getattr(func, "name", "")
                    raw_args = getattr(func, "arguments", "") or "{}"
                    try:
                        parsed_args = json.loads(raw_args) if isinstance(raw_args, str) else dict(raw_args)
                    except Exception:  # noqa: BLE001
                        parsed_args = {}
                    execution = self._skill_runtime.execute_tool(tool_name, parsed_args, self.config.timeout)
                    skill_events.append(
                        {
                            "event_type": "skill_execution",
                            "tool_name": tool_name,
                            "arguments": parsed_args,
                            "result": execution,
                            "ok": bool(execution.get("ok")),
                        }
                    )

                    tc_id = getattr(tc, "id", f"call_{len(tool_call_payload)}")
                    tool_call_payload.append(
                        {
                            "id": tc_id,
                            "type": "function",
                            "function": {"name": tool_name, "arguments": json.dumps(parsed_args, ensure_ascii=True)},
                        }
                    )
                    tool_results.append(
                        {
                            "tool_call_id": tc_id,
                            "tool_name": tool_name,
                            "payload": execution,
                        }
                    )

                messages.extend(build_tool_messages(tool_call_payload, tool_results))
                second_params = dict(litellm_params)
                second_params["messages"] = messages
                second_response = litellm.completion(**second_params)
                content = (second_response.choices[0].message.content or "").strip()
                self._last_skill_events = skill_events
                return {"content": content, "skill_events": skill_events}

            return {"content": (first_message.content or "").strip(), "skill_events": []}

        except litellm.Timeout as e:
            logger.error(f"Timeout logic executed for agent '{self.name}' on model '{self.model}': {e}")
            return {
                "content": f"[Timeout Error: The model '{self.model}' took too long to respond ({self.config.timeout}s)]",
                "skill_events": [],
            }
        except Exception as e:
            logger.error(f"Error getting response from agent '{self.name}' on model '{self.model}': {e}")
            return {"content": f"[Error: Could not generate response. Details: {str(e)}]", "skill_events": []}

    def generate_response(self, context_messages: List[Dict[str, str]], override_params: Optional[Dict[str, Any]] = None) -> str:
        """
        Backward-compatible wrapper that returns only human-readable content.
        """
        result = self.generate_response_with_events(context_messages, override_params=override_params)
        return str(result.get("content", "")).strip()

    def __repr__(self):
        return f"<Agent name={self.name} model={self.model}>"

import types

from rooms.agent import Agent
import rooms.agent as agent_module
from rooms.config import AgentConfig
from rooms.skills_runtime import SkillRuntime


def _build_fake_skill_module():
    module = types.ModuleType("fake_skill_module")

    class FakeSkill:
        __module__ = "fake_skill_module"

        def __init__(self, config=None):
            self.config = config or {}

        def execute(self, params):
            return {"echo": params, "cfg": self.config}

    module.FakeSkill = FakeSkill
    return module


def _build_fake_loader_module():
    module = _build_fake_skill_module()

    class FakeLoader:
        @staticmethod
        def load_skill(skill_id):
            return {
                "module": module,
                "manifest": {"name": skill_id},
                "instructions": "Use tool carefully.",
                "card": {},
            }

        @staticmethod
        def to_openai_tool(bundle):
            skill_id = bundle["manifest"]["name"]
            return {
                "type": "function",
                "function": {
                    "name": skill_id.replace("/", "_"),
                    "description": "fake tool",
                    "parameters": {
                        "type": "object",
                        "properties": {"q": {"type": "string"}},
                    },
                },
            }

    return types.SimpleNamespace(SkillLoader=FakeLoader)


def test_runtime_lazy_loading_skips_import_when_no_skills(monkeypatch):
    cfg = AgentConfig(name="A", system_prompt="S", skills=[])
    runtime = SkillRuntime(cfg)

    def _should_not_import(_name):
        raise AssertionError("Skillware import should not run")

    monkeypatch.setattr("rooms.skills_runtime.importlib.import_module", _should_not_import)
    assert runtime.get_tools() == []
    assert runtime.get_combined_instructions() == ""


def test_runtime_reports_missing_skillware(monkeypatch):
    cfg = AgentConfig(name="A", system_prompt="S", skills=["compliance/tos_evaluator"])
    runtime = SkillRuntime(cfg)

    def _missing(_name):
        raise ModuleNotFoundError("skillware unavailable")

    monkeypatch.setattr("rooms.skills_runtime.importlib.import_module", _missing)
    assert runtime.get_tools() == []
    assert runtime.load_error is not None
    assert "Install with: pip install skillware" in runtime.load_error


def test_runtime_enforces_session_call_limit(monkeypatch):
    cfg = AgentConfig(
        name="A",
        system_prompt="S",
        skills=["compliance/tos_evaluator"],
        max_skill_calls_per_session=0,
    )
    runtime = SkillRuntime(cfg)
    monkeypatch.setattr("rooms.skills_runtime.importlib.import_module", lambda _name: _build_fake_loader_module())
    runtime.get_tools()
    result = runtime.execute_tool("compliance_tos_evaluator", {"q": "hello"}, timeout_s=5)
    assert result["ok"] is False
    assert "Max skill calls per session reached" in result["error"]


def test_agent_executes_tool_and_returns_synthesized_reply(monkeypatch):
    calls = []
    monkeypatch.setattr("rooms.skills_runtime.importlib.import_module", lambda _name: _build_fake_loader_module())

    class _Function:
        def __init__(self, name, arguments):
            self.name = name
            self.arguments = arguments

    class _ToolCall:
        def __init__(self, tc_id, name, arguments):
            self.id = tc_id
            self.function = _Function(name, arguments)

    class _Message:
        def __init__(self, content, tool_calls=None):
            self.content = content
            self.tool_calls = tool_calls or []

    class _Choice:
        def __init__(self, message):
            self.message = message

    class _Response:
        def __init__(self, message):
            self.choices = [_Choice(message)]

    def _fake_completion(**kwargs):
        calls.append(kwargs)
        if len(calls) == 1:
            return _Response(
                _Message(
                    "",
                    tool_calls=[_ToolCall("call_1", "compliance_tos_evaluator", '{"q":"risk"}')],
                )
            )
        return _Response(_Message("Readable final answer"))

    monkeypatch.setattr(agent_module.litellm, "completion", _fake_completion)
    agent = Agent(
        AgentConfig(
            name="A",
            system_prompt="S",
            skills=["compliance/tos_evaluator"],
            skill_settings={"compliance/tos_evaluator": {"mode": "strict"}},
        )
    )

    result = agent.generate_response(context_messages=[])
    assert result == "Readable final answer"
    assert len(calls) == 2
    assert "tools" in calls[0]
    second_messages = calls[1]["messages"]
    assert any(m.get("role") == "tool" for m in second_messages)


def test_wallet_screening_skill_flow_returns_natural_language(monkeypatch):
    """Simulate a flagged wallet check and ensure final output is natural language."""
    bad_wallet = "0x1111111111111111111111111111111111111111"
    tool_name = "finance_wallet_screening"
    calls = []

    module = types.ModuleType("wallet_skill_module")

    class WalletScreeningSkill:
        __module__ = "wallet_skill_module"

        def __init__(self, config=None):
            self.config = config or {}

        def execute(self, params):
            wallet = params.get("wallet", "")
            return {
                "wallet": wallet,
                "risk_level": "high",
                "flagged": wallet == bad_wallet,
                "reason": "Listed in sanctions dataset",
            }

    module.WalletScreeningSkill = WalletScreeningSkill

    class FakeLoader:
        @staticmethod
        def load_skill(skill_id):
            return {
                "module": module,
                "manifest": {"name": skill_id},
                "instructions": "Use this tool to screen wallets for risk flags.",
                "card": {},
            }

        @staticmethod
        def to_openai_tool(bundle):
            return {
                "type": "function",
                "function": {
                    "name": tool_name,
                    "description": "Screen a wallet for risk",
                    "parameters": {
                        "type": "object",
                        "properties": {"wallet": {"type": "string"}},
                        "required": ["wallet"],
                    },
                },
            }

    monkeypatch.setattr("rooms.skills_runtime.importlib.import_module", lambda _name: types.SimpleNamespace(SkillLoader=FakeLoader))

    class _Function:
        def __init__(self, name, arguments):
            self.name = name
            self.arguments = arguments

    class _ToolCall:
        def __init__(self, tc_id, name, arguments):
            self.id = tc_id
            self.function = _Function(name, arguments)

    class _Message:
        def __init__(self, content, tool_calls=None):
            self.content = content
            self.tool_calls = tool_calls or []

    class _Choice:
        def __init__(self, message):
            self.message = message

    class _Response:
        def __init__(self, message):
            self.choices = [_Choice(message)]

    def _fake_completion(**kwargs):
        calls.append(kwargs)
        if len(calls) == 1:
            return _Response(
                _Message(
                    "",
                    tool_calls=[
                        _ToolCall(
                            "call_wallet",
                            tool_name,
                            '{"wallet":"0x1111111111111111111111111111111111111111"}',
                        )
                    ],
                )
            )
        return _Response(
            _Message(
                "I checked the wallet and it is high risk because it appears in a sanctions list."
            )
        )

    monkeypatch.setattr(agent_module.litellm, "completion", _fake_completion)

    agent = Agent(
        AgentConfig(
            name="RiskAnalyst",
            system_prompt="Screen wallets and explain risk clearly.",
            model="ollama/gemma4:e2b",
            skills=["finance/wallet_screening"],
        )
    )

    reply = agent.generate_response([{"role": "user", "content": f"Check wallet {bad_wallet}"}])
    assert "high risk" in reply.lower()
    assert "{" not in reply and "}" not in reply
    assert len(calls) == 2
    tool_msgs = [m for m in calls[1]["messages"] if m.get("role") == "tool"]
    assert len(tool_msgs) == 1
    assert '"flagged": true' in tool_msgs[0]["content"].lower()

import types

from rooms.skills_cli import _normalize_skill_record, inspect_skill, list_skills, suggest_skills


def test_normalize_skill_record_string():
    out = _normalize_skill_record("finance/wallet_screening")
    assert out["id"] == "finance/wallet_screening"
    assert out["title"] == "finance/wallet_screening"


def test_list_skills_via_loader_api(monkeypatch):
    class FakeLoader:
        @staticmethod
        def list_skills():
            return [
                {"id": "finance/wallet_screening", "description": "Wallet checks"},
                {"id": "legal/contract_parser", "description": "Parse contracts"},
            ]

    monkeypatch.setattr(
        "rooms.skills_cli.importlib.import_module",
        lambda _name: types.SimpleNamespace(SkillLoader=FakeLoader),
    )
    skills, err = list_skills()
    assert err is None
    assert len(skills) == 2
    assert skills[0]["id"] == "finance/wallet_screening"


def test_inspect_skill_returns_manifest(monkeypatch):
    class FakeLoader:
        @staticmethod
        def load_skill(_skill_id):
            return {
                "manifest": {
                    "name": "finance/wallet_screening",
                    "version": "1.2.3",
                    "description": "Screen wallet risk",
                    "inputs": {"wallet": "string"},
                },
                "instructions": "Use tool for wallet checks.",
            }

    monkeypatch.setattr(
        "rooms.skills_cli.importlib.import_module",
        lambda _name: types.SimpleNamespace(SkillLoader=FakeLoader),
    )
